import { Component, createEffect, createSignal, Show } from "solid-js";

import { getMajorLeader, getPlayerDiplomacy } from "#core/ui/utilities/diplomacy-utilities.js";
import { getPlayerColorVariants } from "#core/ui/utilities/utilities-color.js";
import { LeaderIconComponent, LeaderIconProps } from "#core/ui-next/components/portrait-icon.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface PortraitVictoryIconData {
	playerId: PlayerId;
	size: number;
	desaturate?: boolean;
	isVictory: boolean;
	isDomination: boolean;
	isDefeat: boolean;
}

const PortraitIconVictoryComponent: Component<PortraitVictoryIconData> = (props) => {
	const [iconProps, setIconProps] = createSignal<LeaderIconProps>();

	const [backgroundColor, setBackgroundColor] = createSignal<string>("");
	createEffect(() => {
		if (props.playerId === PlayerIds.NO_PLAYER) {
			return;
		}

		const majorLeader = getMajorLeader(props.playerId);

		if (!majorLeader) {
			return;
		}
		const leaderType = GameInfo.Leaders.lookup(majorLeader.leaderType)?.LeaderType;

		const playerDiplomacy = getPlayerDiplomacy(majorLeader);
		if (!playerDiplomacy) {
			return;
		}

		let portraitContext = "";
		if (props.isDefeat) {
			portraitContext = "LEADER_ANGRY";
		} else {
			portraitContext = "LEADER_HAPPY";
		}

		setIconProps({
			icon: UI.getIconCSS(leaderType ?? "UNKNOWN_LEADER", portraitContext),
			size: props.size,
			desaturate: props.desaturate,
		});

		const variants = getPlayerColorVariants(props.playerId);
		if (variants) {
			setBackgroundColor(variants.secondaryColor.mainColor);
		}
	});
	return (
		<div class={`relative flex size-${props.size}`}>
			<div
				class={`absolute portrait-icon-container relative bg-center bg-no-repeat bg-contain size-52`}
				style={{
					"background-image": "url(blp:victory_hex_backingGlow)",
				}}
				data-name="Portrait-Icon"
			/>
			<div
				class={`portrait-icon__laurels bg-center bg-no-repeat bg-contain size-60 absolute -ml-7 -mt-9`}
				style={{
					"background-image": "url(blp:popup_gold_laurels)",
				}}
			/>
			<Show when={props.isVictory && props.isDomination}>
				<div
					class={`portrait-icon__domination bg-center bg-no-repeat bg-contain size-52 absolute -mt-2\\.5 -ml-2`}
					style={{
						"background-image": "url(blp:endScreen_dominationSwords)",
					}}
				/>
			</Show>
			<Show when={!props.isVictory && props.isDomination}>
				<div
					class={`portrait-icon__domination bg-center bg-no-repeat bg-contain size-52 absolute -mt-2\\.5 -ml-2`}
					style={{
						"background-image": "url(blp:endScreen_defeatSwords)",
					}}
				/>
			</Show>
			<div
				class={`portrait-icon__domination bg-center bg-no-repeat bg-contain size-48 absolute`}
				style={{
					"background-image": "url(blp:final_leader-hex)",
					// eslint-disable-next-line solid/style-prop
					"fxs-background-image-tint": backgroundColor(),
				}}
			/>

			<div
				class={`portrait-icon__background bg-center bg-no-repeat bg-contain size-40 absolute ml-4 mt-4`}
				style={{
					"background-image": "url(blp:victory_gold-hex_endScreen)",
				}}
			/>
			<div class="absolute -mt-3\.5 -ml-2\.5">
				<Show when={iconProps()}>{(icon) => <LeaderIconComponent {...icon()} />}</Show>
			</div>
		</div>
	);
};

export const PortraitIconVictory = ComponentRegistry.register({
	name: "PortraitIconVictory",
	createInstance: PortraitIconVictoryComponent,
});
